class Solution(object):
    def maxScore(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        def gcd(a, b):
            return a if b == 0 else gcd(b, a % b)
        n = len(nums)
        g = [[0 for _ in range(n)] for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                g[i][j] = gcd(nums[i], nums[j])
        dp = [0] * (1 << n)
        for k in range(1 << n):
            cnt = bin(k).count("1")
            if cnt % 2 == 1:
                continue
            for i in range(n):
                if (k >> i) & 1 == 0:
                    continue
                for j in range(i + 1, n):
                    if (k >> j) & 1 == 0:
                        continue
                    dp[k] = max(dp[k], dp[k ^ (1 << i) ^ (1 << j)] + cnt // 2 * g[i][j])
        return dp[-1]
